#include <string>
#include <vector>
#include <sstream>
#include <algorithm>
using namespace std;

class Solution {
public:
    string reverseWordsWithMaxVowels(string s) {
        auto isVowel = [](char c) {
            c = tolower(c);
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        };
        stringstream ss(s);
        string word;
        vector<string> words;
        vector<int> counts;
        int max_v = 0;
        while (ss >> word) {
            words.push_back(word);
            int v = 0;
            for (char c : word) if (isVowel(c)) v++;
            counts.push_back(v);
            max_v = max(max_v, v);
        }
        string res = "";
        for (int i = 0; i < (int)words.size(); i++) {
            if (counts[i] == max_v && max_v > 0) {
                reverse(words[i].begin(), words[i].end());
            }
            if (i > 0) res += " ";
            res += words[i];
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public String reverseWordsWithMaxVowels(String s) {
        String[] words = s.split(" ");
        Set<Character> vowels = new HashSet<>(Arrays.asList('a','e','i','o','u','A','E','I','O','U'));
        int[] counts = new int[words.length];
        int maxV = 0;
        for (int i = 0; i < words.length; i++) {
            int cnt = 0;
            for (char c : words[i].toCharArray()) if (vowels.contains(c)) cnt++;
            counts[i] = cnt;
            maxV = Math.max(maxV, cnt);
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < words.length; i++) {
            if (counts[i] == maxV && maxV > 0) {
                sb.append(new StringBuilder(words[i]).reverse());
            } else {
                sb.append(words[i]);
            }
            if (i < words.length - 1) sb.append(" ");
        }
        return sb.toString();
    }
}

var reverseWordsWithMaxVowels = function(s) {
    const words = s.split(' ');
    const vowels = new Set('aeiouAEIOU');
    const counts = words.map(w => [...w].filter(c => vowels.has(c)).length);
    const maxV = counts.length ? Math.max(...counts) : 0;
    return words.map((w, i) => {
        if (counts[i] === maxV && maxV > 0) return w.split('').reverse().join('');
        return w;
    }).join(' ');
};
